// Helper to merge custom data with SWAPI data
export function useMergedPlanetWithCustom(
  planet: { id: string; name: string } | undefined,
) {
  const { data: customData } = useCustomPlanet(planet?.id || null);
  
  return useMemo(() => {
    if (!planet) return undefined;
    
    return {
      ...planet,
      customNotes: customData?.customNotes,
      userRating: customData?.userRating,
      isFavorite: customData?.isFavorite || false,
      customImage: customData?.customImage,
      tags: customData?.tags,
    };
  }, [planet, customData]);
}
